```cpp
#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int N = 5000;

vector<int> primes;
vector<vector<int>> factor; // factor[i][j] = exponent of j-th prime in i!

long long comb(int m, int n) {
    long long res = 1;
    int P = primes.size();
    vector<int> fnm(P);
    // fnm = factor[n] + factor[m]
    for (int i = 0; i < P; ++i) {
        fnm[i] = factor[n][i] + factor[m][i];
    }

    for (int w = 1; w <= m; ++w) {
        long long r = 1;
        for (int i = 0; i < P; ++i) {
            int exp = fnm[i] - factor[w][i] - factor[n - w][i] - factor[m - w][i];
            long long base = primes[i];
            long long cur = 1;
            // fast pow
            while (exp > 0) {
                if (exp & 1) cur = cur * base % MOD;
                base = base * base % MOD;
                exp >>= 1;
            }
            r = r * cur % MOD;
        }
        res += r;
        if (res >= MOD) res -= MOD;
    }
    return res % MOD;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    array<int, 3> abc;
    cin >> abc[0] >> abc[1] >> abc[2];
    sort(abc.begin(), abc.end());

    // Sieve
    vector<bool> sieve(N + 1, false);
    sieve[0] = sieve[1] = true;
    for (int p = 2; p <= N; ++p) {
        if (!sieve[p]) {
            primes.push_back(p);
            if ((long long)p * p <= N) {
                for (int q = p * p; q <= N; q += p) {
                    sieve[q] = true;
                }
            }
        }
    }

    int P = primes.size();
    factor.assign(N + 1, vector<int>(P, 0));

    // Exponents in j
    for (int i = 0; i < P; ++i) {
        int p = primes[i];
        for (long long pp = p; pp <= N; pp *= p) {
            for (int j = pp; j <= N; j += pp) {
                factor[j][i]++;
            }
        }
    }

    // Prefix sums for factorials
    // factor[0] is all zeros.
    for (int j = 1; j <= N; ++j) {
        for (int i = 0; i < P; ++i) {
            factor[j][i] += factor[j-1][i];
        }
    }

    long long ans = comb(abc[0], abc[1]);
    ans = ans * comb(abc[0], abc[2]) % MOD;
    ans = ans * comb(abc[1], abc[2]) % MOD;
    cout << ans << "\n";

    return 0;
}
```

